const SRC_ORDER = { orders: 0, shipments: 1, settlements: 2, allocations: 3 };
const validationErrors = S.validation_errors.slice().sort(function (a, b) {
  return (
    cmp(SRC_ORDER[a.source], SRC_ORDER[b.source]) ||
    cmp(a.row_number, b.row_number) ||
    cmp(a.field || "", b.field || "") ||
    cmp(a.code, b.code)
