}
const exposureRows = del.filter(function (r) {
  return (
    r.settlement_completeness === "UNKNOWN" ||
    ((r.settlement_completeness === "UNSETTLED" ||
      r.settlement_completeness === "PARTIALLY_SETTLED") &&
      r.due_date_status === "UNKNOWN")
