const unalloc = settlementSummary.filter(function (s) {
  return !s.over_allocated;
});
const excByType = {};
exceptions.forEach(function (e) {
  excByType[e.type] = (excByType[e.type] || 0) + 1;
});
const excByTypeSorted = {};
Object.keys(excByType)
  .sort()
  .forEach(function (k) {
    excByTypeSorted[k] = excByType[k];
