const adjustmentSettlements = settlementSummary.filter(
  function (s) {
    return s.entry_type === "ADJUSTMENT";
  }
);

const totalAdjustmentPaisa = sumKnown(
  adjustmentSettlements.map(function (s) {
    return s.net_paid_paisa;
