);

const unallocatedAdjustmentPaisa = sumKnown(
  adjustmentSettlements.map(function (s) {
    return s.unallocated_paisa;
  })
);

// Accounting invariant:
// Total = Allocated + Unallocated
if (
  !Number.isSafeInteger(totalAdjustmentPaisa) ||
  !Number.isSafeInteger(allocatedAdjustmentPaisa) ||
  !Number.isSafeInteger(unallocatedAdjustmentPaisa) ||
  totalAdjustmentPaisa !==
    allocatedAdjustmentPaisa + unallocatedAdjustmentPaisa
