const kpis = {
  expected_receivable_paisa: sumKnown(
    del.map(function (r) {
      return r.expected_receivable_paisa;
    }),
  ),
  verified_paid_paisa: sumKnown(
    del.map(function (r) {
      return r.verified_paid_paisa;
    }),
