      return r.adjustment_paisa;
    }),
  ),
  total_adjustment_paisa: totalAdjustmentPaisa,
  allocated_adjustment_paisa: allocatedAdjustmentPaisa,
  unallocated_adjustment_paisa: unallocatedAdjustmentPaisa,
